def read_ints():
    return list(map(int, input().split()))

n, m = read_ints()
graph = [[] for _ in range(n + 1)]

for _ in range(m):
    x, y = read_ints()
    graph[x].append(y)

# Find the number of cities with no incoming edges
in_degree = [0] * (n + 1)
for city in range(1, n + 1):
    for neighbor in graph[city]:
        in_degree[neighbor] += 1

# Count the number of cities with no incoming edges
separated_cities = sum(1 for degree in in_degree if degree == 0)

# If all cities have incoming edges, we need to separate at least one city
if separated_cities == 0:
    separated_cities = 1

print(separated_cities)
